    public function own(Request $request)
    {
        $profile = TicketAssignmentSetting::query()->with(['user', 'categories', 'tags'])->where('user_id', $request->user()->id)->first();
        if (! $profile) {
            $profile = new TicketAssignmentSetting(['user_id' => $request->user()->id, 'is_assignable' => true, 'max_open_tickets' => 10]);
            $profile->setRelation('user', $request->user())->setRelation('categories', new Collection)->setRelation('tags', new Collection);
        }

        return $this->profileResource($profile);
    }

