    public function ownHistory(Request $request, DomainApiAudit $audit)
    {
        return DomainApiAuditResource::collection($audit->query('ticket')->where('event', 'like', 'ticket.assignment.profile.%')
            ->where('properties->context->profile_user_id', $request->user()->id)->orderByDesc('id')->paginate(DomainApiRead::pageSize($request))->withQueryString());
    }

    #[OA\Get(path: '/api/v1/ticket-assignment-profiles', operationId: 'ticketTicketAssignmentApiControllerprofiles', security: [['bearerAuth' => []]], tags: ['Tickets'], parameters: [new OA\Parameter(name: 'page', in: 'query', schema: new OA\Schema(type: 'integer', minimum: 1)), new OA\Parameter(name: 'per_page', in: 'query', schema: new OA\Schema(type: 'integer', minimum: 1, maximum: 100, default: 25))], x: ['required-scopes' => ['tickets.assignment.read'], 'domain-permissions' => 'ticket.manage_settings', 'additional-domain-permissions' => []], responses: [new OA\Response(response: 200, description: 'Explicit persisted read-back or preview', content: new OA\JsonContent(type: 'object', required: ['data', 'meta', 'links'], properties: [new OA\Property(property: 'data', type: 'array', items: new OA\Items(ref: '#/components/schemas/TicketAssignmentProfileReadback')), new OA\Property(property: 'meta', ref: '#/components/schemas/ParityPageMeta'), new OA\Property(property: 'links', ref: '#/components/schemas/ParityPageLinks')])), new OA\Response(response: 401, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError')), new OA\Response(response: 403, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError')), new OA\Response(response: 404, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError')), new OA\Response(response: 422, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError'))])]
    public function profiles(Request $request)
    {
        $query = TicketAssignmentSetting::query()->select('ticket_assignment_settings.*')->with(['user', 'categories', 'tags'])
            ->addSelect(['open_ticket_count' => Ticket::query()->selectRaw('count(*)')->whereColumn('owner_id', 'ticket_assignment_settings.user_id')
                ->whereHas('status', fn ($q) => $q->where('is_closed', false))]);

        return TicketAssignmentProfileResource::collection($query->orderBy('user_id')->orderBy('id')->paginate(DomainApiRead::pageSize($request))->withQueryString());
    }

