    public function destroyRule(Request $request, TicketAssignmentRule $rule, TicketAssignmentRuleEditor $editor)
    {
        $editor->delete($rule, $request->user());

        return response()->json(['data' => ['id' => $rule->id, 'deleted' => true]]);
    }

    private function profileResource(TicketAssignmentSetting $profile): TicketAssignmentProfileResource
    {
        $profile->setAttribute('open_ticket_count', Ticket::query()->where('owner_id', $profile->user_id)->whereHas('status', fn ($q) => $q->where('is_closed', false))->count());

        return new TicketAssignmentProfileResource($profile);
    }
}
